void Solver::bump_var(int var, double coeff) {
    // Increment activity with the given coefficient
    double delta = var_inc * coeff;
    activity[var] += delta;

    // Scale down all activities and var_inc only when a single activity exceeds a high threshold.
    // This reduces the frequency of the O(vars) scaling loop compared to the original implementation.
    const double THRESH = 1e120;   // higher threshold to postpone scaling
    const double SCALE  = 1e-120;  // corresponding scaling factor

    if (activity[var] > THRESH) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // Keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) vsids.update(var);
}
